\label{def-BA-divisor-formal}
	The \textit{Baker--Akhiezer divisor} 
	\footnote{In local frames adapted to $\pi^\ast L$, the line bundle $\pi^\ast(K^{-1}) \mathcal{L}_{(E,\phi)}$ of eigenvectors of $\pi^\ast(\phi)$ has sections of the form $\left(\begin{smallmatrix} v + a(z) \\ c(z) \end{smallmatrix} \right)$,
	reminiscent of the Baker--Akhiezer function in the theory of integrable systems \cite{DT23}, \cite[Remark~2.3]{Dinh24wobbly}.}
	$\widetilde{D}_i(\phi)$ of the data $(L \overset{i}{\rightarrow} E, \phi)$ is the zero divisor of the morphism of line bundles on $\widetilde{C}$
	\begin{equation} \label{BA-div-def-composition}
		\pi^\ast(L) \overset{\pi^\ast i}{\longrightarrow} \pi^\ast(E) \longrightarrow \mathcal{L}_{(E, \phi)}.
	\end{equation}

\cite{DT23}
	\label{prop-basic-properties-BA-divisor}
	Let $(E, \phi)$ be a Higgs bundle with smooth spectral curve and 
	$L \overset{i}{\rightarrow} E$ an injection. 
	Then $\pi^\ast(p) < \widetilde{D}_i(\phi)$ if and only if $i$ vanishes at $p$ and 
	\begin{equation*}
		D_i(\phi) = \mathrm{Nm}(\widetilde{D}_i(\phi)).
	\end{equation*}

\label{thm-wobbly-Q-special}
	Let $\widetilde{C}_q \overset{\pi}{\rightarrow} C$ be a non-degenerate spectral curve
	and $\mathcal{L}$ a line bundle on $\widetilde{C}_q$.
	Assume that $E = \pi_\ast \mathcal{L}$ is semistable, and let $\det(E) = \Lambda$.
	Then $E$ is wobbly if and only if
	\begin{equation*}
		\mathcal{L} \simeq \pi^\ast(L) \otimes \mathcal{O}_{\widetilde{C}_q}(\widetilde{D})
	\end{equation*}
	where $L$ is a line bundle on $C$ and $\widetilde{D}$ is an effective divisor on $\widetilde{C}_q$ with $Q_{\mathrm{Nm}(\widetilde{D})} \neq 0$.
	Furthermore, if $\widetilde{D}$ has no summand of the form $\pi^\ast(P)$
	for some effective divisor $P$ on $C$, then
	$E$ admits an embedding $L \overset{i}{\hookrightarrow} E$
	and there is a canonical bijection between the corresponding space of nilpotent Higgs fields
	\begin{equation*}
		H^0\left( C, K L^2 \Lambda^{-1} \right) \simeq
		\left\{ \phi \in H^0(C, \mathrm{End}(E)\otimes K) \text{ nilpotent},
		\ker(\phi) = i(L) \right\}
	\end{equation*}
	and $Q_{\mathrm{Nm}(\widetilde{D})}$.

A projective structure is a maximal atlas $\left\{ U_\alpha \right\}_{\alpha \in \mathcal{I}}$ of $C$
	together with local holomorphic functions $\{ w_\alpha: U_\alpha \rightarrow \mathbb C\}$
	the values of which are related by Möbius transformations, 
	i.e. for all $x\in U_\alpha \cap U_\beta$,
	\begin{align}\label{PSL_2-action-projective-structure}
		&w_\beta (x) = \frac{a_{\beta \alpha} w_\alpha (x) + b_{\beta \alpha}}{c_{\beta \alpha} w_\alpha (x) + d_{\beta \alpha}}, 
		&\begin{pmatrix} a_{\beta \alpha} & b_{\beta \alpha} \\ c_{\beta \alpha} & d_{\beta \alpha} \end{pmatrix} \in \operatorname{SL}_2(\mathbb C).
	\end{align}
	Apparent singularities are where $d w_\alpha = 0$;
	the order of an apparent singularity is the order of the zero of $d w_\alpha$ at that point.

{ 
		See \cite[Section~4.1]{Dinh24} and \cite[Chapter~5]{dinh-thesis}.
