\label{lemma-linear-system-right-side}
	Fix $i \in \{1,2\}$. \\
	1. The functions $\frac{1}{u} R^{(i)}_{u, +}(-u)$ and $-\frac{1}{u} R^{(i)}_{u,-}(u)$ are holomorphic on $U$ with variable $u = z(x_+)$. 
	Furthermore, their evaluations at $u = 0$ are equal. \\
	2. For each fixed $z$, the limit 
	\begin{align}
		\check{R}^{(i)} (z) \coloneqq \underset{u \rightarrow 0}{\lim} \frac{1}{u}\left( R^{(i)}_{u,+} (z) - R^{(i)}_{u,-}(z) \right)
		\label{shift-after-collision}
	\end{align}
	exists. 
	These limits define a holomorphic function on $U$ with variable $z$.

\label{lemma-tune-limit-hol-q}
	Let $x_0$, $x_3$, ..., $x_{d}$ satisfy condition \eqref{condition-neighborhood},
	$\nu_0\in \mathbb C$, and $q \in H^0(K^2)$ a holomorphic quadratic differential.
	Then there exist holomorphic functions $\nu_3(u)$, ..., $\nu_{d}(u): z(U) \rightarrow \mathbb C$ 
	and $\nu_\pm(u): z(U\setminus \{x_0\}) \rightarrow \mathbb C$ with Laurent expansions at $u =0$ of the forms \eqref{eqn-form-B} or \eqref{eqn-form-D} (with $\nu_0$ as the coefficient of order $u^0$),
	and a family of holomorphic quadratic differentials $\{q^{(0)}_u\}_{u\in z(U)}$ such that
	\begin{enumerate}[(i)]
		\item $q^{(0)}_u$ solves the linear system \eqref{linear-system-total} defined by $\nu_\pm(u)$, $\nu_3(u)$, ..., $\nu_d(u)$ for $u\neq 0$;
		\item $q^{(0)}_0 = q$ solves the corresponding limit linear system \eqref{linear-system-total-limit}.
	\end{enumerate}

\label{lemma-db-limit-1}
	Let $x_0$, $x_3$, ..., $x_d$ be distinct points on $C$, 
	$(U,z)$ a coordinate neighborhood of $x_0$ with $z(x_0) = 0$,
	$\nu_{\pm}(u) = \mp \frac{1}{4u} + \nu_0 \pm \nu' u + \mathcal{O}(u^2)$ holomorphic functions on $U\setminus \{x_0 \}$,
	and $q^{(i)}_{u, \pm}$ defined as in \eqref{building-blocks-0} for $u \in z\left( U \right)$, $u \neq 0$.
	Then the family of meromorphic quadratic differentials	
	\begin{align} \label{family-merom-q-db}
		&\sum_{s\in \{\pm\}} \nu_s(u) q^{(1)}_{u, s} - \frac{3}{4} \sum_{s\in \{\pm\}} q^{(2)}_{u, s},
	\end{align}
	which is parameterized by $U \setminus \{x_0\}$, 
	extends to a family parameterized by $U$.
	The meromorphic quadratic differential $q^{(2)}_{x_0}$ 
	corresponding to the extension to $x_0$
	is holomorphic on $C \setminus \{x_0\}$,
	vanishes at $x_3$, ..., $x_{d}$,
	and on $U$ takes the form
	\begin{align}\label{q_x_0-local-form}
		q^{(2)}_{x_0} 
		\equiv q^{(2)}_{x_0}(\nu_0) 
		= \left[ - \frac{2 }{z^2}  + \frac{2 \nu_0 }{z} 
		+ 2\nu_0  R^{(1)}_{0}(z)
		-\frac{1}{4} \check{R}^{(1)}(z) 
		- \frac{3}{2}R^{(2)}_0(z) \right] dz^2,
	\end{align}
	where $\check{R}^{(1)}(z)$ is defined in part 2 of \Cref{lemma-linear-system-right-side}
	and $R^{(i)}_0(z)$ defined in \eqref{common-building-block-limit}.

\label{prop-double-as}
	Let $\mathcal{D}$ be a branched projective structure with $\mathrm{div}(\mathcal{D}) = 2x_0 + x_3 + ... + x_d$ being $Q$-generic and $d \leq 3g-3$.
	Then there exists a coordinate neighborhood $(U, z)$ centred at $x_0$ 
	and a family of branched projective structures $\{\mathcal{D}_u\}_{u\in z(U)}$ parametrized by $U$ such that
	\begin{enumerate}[(i)]
		\item $\mathcal{D}_0 = \mathcal{D}$;
		\item for $u\neq 0$, $\mathrm{div}(\mathcal{D}_u) = x_+ + x_- + x_3 + \dots x_d$ with $x_\pm \in U$ and $z(x_\pm) = \pm u$;
		\item for $u\neq 0$, the accessory parameters $\nu_\pm(u)$ of $x_\pm$ w.r.t. the local coordinate $z$ have Laurent expansions as functions of $u$ of Form (D) \eqref{eqn-form-D},
		where $2\nu_0^\mathcal{D}$ is the accessory parameter of the double apparent singularity $x_0$ of $\mathcal{D}$.
	\end{enumerate}
	Furthermore, this family defines via taking monodromy a holomorphic map $U \rightarrow \mathrm{Hom}(\pi_1, \mathrm{PSL}_2)$, which is injective for $d < 2g-2$.

The proof follows directly from \Cref{lemma-bb-limit-1}.
{ 
	The apparency constraints \eqref{SL-operator_residue-constraint-1} at $x_3, \dots, x_d$ hold for all $u \neq 0$ and pass to the limit $u \rightarrow 0$ by continuity. In contrast to \Cref{prop-db-limit-2}, there is no constraint to check at $x_0$, since $\Delta q^{(0)}_{x_0}$ is holomorphic.
}

\label{prop-bb-limit-3}
	Let $\mathcal{D}$ be a branched projective structure with $\mathrm{div}(\mathcal{D}) = x_3+ ... + x_{d}$ for $d \leq 3g-3$,
	and $x_0\in C$ such that $2x_0 + x_3 + ... x_d$ is $Q$-generic.
	Then there exists a coordinate neighborhood $(U, z)$ centred at $x_0$
	and a family of branched projective structures $\{\mathcal{D}_u\}_{u\in z(U)}$ parametrized by $U$ such that
	\begin{enumerate}[(i)]
		\item $\mathcal{D}_0 = \mathcal{D}$;
		\item for $u\neq 0$, $\mathrm{div}(\mathcal{D}_u) = x_+ + x_- + x_3 + \dots x_d$ with $x_\pm \in U$ and $z(x_\pm) = \pm u$;
		\item for $u\neq 0$, the accessory parameters $\nu_\pm(u)$ of $x_\pm$ w.r.t. the local coordinate $z$ have Laurent expansions as functions of $u$ of Form (B) \eqref{eqn-form-B}.
	\end{enumerate}
	Furthermore, this family defines via taking monodromy a holomorphic map $U \rightarrow \operatorname{Hom}(\pi_1, \mathrm{PSL}_2)$, which is injective for $d < 2g-2$.

Given a projective structure with developing map $A: \widetilde{\Sigma} \rightarrow \mathbb{P}^1$, we say that two paths $\gamma_1$ and $\gamma_2$ on $\Sigma$, both defined on the same interval $[0, T]$ are \textit{twin paths} if they overlap once developed, i.e.
	\begin{enumerate}
		\item $\gamma_1(0) = \gamma_2(0)$ is an apparent singularity;
		\item If $\alpha: [-T, T] \rightarrow \Sigma$ is given by $\alpha(t) = \gamma_1(t)$ for $t \geq 0$ and $\gamma_2(-t)$ for $t \leq 0$, then the developed $\overline{\alpha}$ of $\alpha$ is even: $\overline{\alpha}(t) = \overline{\alpha}(-t)$.
	\end{enumerate} 
	In particular, if $\gamma_1$ and $\gamma_2$ are embedded and disjoint except at $\gamma_1(0) = \gamma_2(0)$ then we call them \textit{embedded twin paths}.

\label{thm-twinpaths-bubble}
	Let $\sigma'$ be a branched projective structure on $\Sigma$, and let $\gamma_1$, $\gamma_2$ be twin paths bounding a bubble $\Delta$.
	Then $\sigma' = \mathrm{Bub}(\sigma, \gamma)$, where $\sigma$ is obtained from $\sigma'$ by collapsing $\Delta$ and identifying $\gamma_1(t)$ with $\gamma_2(t)$, and $\gamma$ is the resulting segment.

Let $\{\mathcal{D}_u\}$ be the family of projective structures as in \Cref{prop-bb-limit-3}, with accessory parameters $\nu_\pm(u)$ of Form B \eqref{eqn-form-B} 
	and $\mathcal{D} = \partial^2 + q_0$ as the $u \rightarrow 0$ limit. 
	Let $\mathcal{Q}$ be the corresponding relative quadratic differential on $S$.
	Then for nonzero $u$ and in local chart $(u, w)$, 
	\begin{equation}\label{eqn-pullback-Q-2}
		\beta^\ast \mathcal{Q}(u, w) =  \left( \frac{-3/4}{(w-1)^2} + \frac{-3/4}{(w+1)^2} + \frac{u \nu_+(u)}{w-1} + \frac{u \nu_-(u)}{w+1} + u^2 g_u(uw) \right) dw^2, 
		\qquad u\neq 0.
	\end{equation}
	The extension of $\beta^\ast \mathcal{Q}$ to $\pi^{-1}(0) \simeq C \cup_{x_0} \mathbb{E}$ restricts to $q_0$ on $C$ and
	\begin{equation}\label{eqn-limit-P1}
		\widetilde{\mathcal{Q}}_0 \mid_{\mathbb{E}} (w) = \frac{-3}{(w-1)^2 (w+1)^2} dw^2
	\end{equation}
	on the exceptional divisor $\mathbb{E} \simeq \mathbb{P}^1$.

\begin{proof}
	1. We need to show that the $u\rightarrow 0$ limit of $\frac{1}{u} R^{(i)}_{u,+}(-u)$ and $-\frac{1}{u} R^{(i)}_{u,-}(u)$ exist and are equal.
	Consider the Taylor expansion of $R^{(i)}_{0}(z_1, z) = \sum_{m, n \geq 0} R^{(i)}_{m,n} z_1^m z^n$ at its zero $(z_1, z) = (0,0)$.
	Since $R^{(i)}_{0,0} = 0$, 
	\begin{align*}
		R^{(i)}_{u,-}(u) &\coloneqq R^{(i)}_{0}(-u, u) = - \left( R_{1,0} - R_{0,1} \right) u + \mathcal{O}(u^2), \\
		R^{(i)}_{u,+}(-u) &\coloneqq R^{(i)}_{0}(u, -u) =  \left( R_{1,0} - R_{0,1} \right) u + \mathcal{O}(u^2).
	\end{align*}
	It follows that
	\begin{align}
		\underset{u \rightarrow 0}{\lim} \frac{1}{u} R^{(i)}_{u,+}(-u) 
		= - \underset{u \rightarrow 0}{\lim} \frac{1}{u} R^{(i)}_{u,-}(u).
	\end{align}
	2. For each fixed $z$, it follows from the Taylor expansion $R^{(i)}_{0}(z_1, z) = \sum_{m, n \geq 0} R^{(i)}_{m,n} z_1^m z^n$ that, 
	\begin{align*}
		R^{(i)}_{u,+}(z) - R^{(i)}_{u,-}(z) 
		= 2u \sum_{n\geq 0} R^{(i)}_{1,n}z^n + 2u^3 \sum_{n\geq 0} R^{(i)}_{3,n} z^n + 2u^5 \sum_{n\geq 0} R^{(i)}_{5,n} z^n + ...
	\end{align*}
	is a holomorphic function on $(U,u)$ that vanishes at $u = 0$; we can calculate
	\begin{align}
		\underset{u \rightarrow 0}{\lim} \frac{1}{u}\left( R^{(i)}_{u,+}(z) - R^{(i)}_{u,-}(z) \right) = 2 \sum_{n\geq 0} R^{(i)}_{1,n}z^n.
	\end{align}
\end{proof}

